import 'package:flutter/material.dart';
import 'package:provider/provider.dart';
import '../providers/media_provider.dart';
import 'detail_screen.dart';
class SearchScreen extends StatefulWidget{const SearchScreen({super.key});@override State<SearchScreen> createState()=>_SearchScreenState();}
class _SearchScreenState extends State<SearchScreen>{final c=TextEditingController();List results=[];bool loading=false;Future<void> go()async{setState(()=>loading=true);results=await context.read<MediaProvider>().search(c.text,'ar');if(mounted)setState(()=>loading=false);} @override void dispose(){c.dispose();super.dispose();}@override Widget build(BuildContext context){return Scaffold(appBar:AppBar(title:const Text('البحث')),body:Column(children:[Padding(padding:const EdgeInsets.all(12),child:TextField(controller:c,onSubmitted:(_)=>go(),decoration:InputDecoration(hintText:'ابحث عن فيلم أو مسلسل أو أنمي',suffixIcon:IconButton(onPressed:go,icon:const Icon(Icons.search))))),if(loading)const LinearProgressIndicator(),Expanded(child:GridView.builder(padding:const EdgeInsets.all(12),gridDelegate:const SliverGridDelegateWithFixedCrossAxisCount(crossAxisCount:3,crossAxisSpacing:10,mainAxisSpacing:10,childAspectRatio:.62),itemCount:results.length,itemBuilder:(_,i){final x=results[i];return InkWell(onTap:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>DetailScreen(item:x))),child:Column(children:[Expanded(child:x.posterUrl==null?const Icon(Icons.movie):Image.network(x.posterUrl!,fit:BoxFit.cover,errorBuilder:(_,__,___)=>const Icon(Icons.broken_image))),Text(x.title,maxLines:2,overflow:TextOverflow.ellipsis)]));}))]));}}
